"""Regenerate AVOS protobuf clients and check committed output."""

import argparse
import difflib
import os
from pathlib import Path
import re
import subprocess
import sys
import tempfile
import venv

ROOT = Path(__file__).resolve().parents[3]

GO_SERVICES = {
    "checkoutservice": ["demo.proto"],
    "frontend": ["demo.proto", "shoppingassistant.proto"],
    "productcatalogservice": ["demo.proto"],
    "shippingservice": ["demo.proto"],
}

PYTHON_SERVICES = {
    "emailservice": ("legacy", "demo.proto"),
    "recommendationservice": ("legacy", "demo.proto"),
    "shoppingassistantservice": ("assistant", "shoppingassistant.proto"),
}


def run(*command, env=None):
    subprocess.run(command, cwd=ROOT, env=env, check=True)


def generated_start(text, suffix):
    markers = (
        ["// Code generated by protoc-gen-go"]
        if suffix == ".go"
        else ["# -*- coding: utf-8 -*-", "# Generated by"]
    )
    positions = [text.find(marker) for marker in markers]
    positions = [position for position in positions if position >= 0]
    if not positions:
        raise RuntimeError("Generated-code header was not found")
    return min(positions)


def python_environment(directory, grpc_version, protobuf_version):
    venv.EnvBuilder(with_pip=True).create(directory)
    python = str(directory / "bin" / "python")
    run(
        python, "-m", "pip", "install", "--only-binary=:all:",
        f"grpcio-tools=={grpc_version}",
        f"grpcio=={grpc_version}",
        f"protobuf=={protobuf_version}",
        "setuptools==80.9.0",
    )
    run(python, "-m", "pip", "check")
    run(python, "-m", "grpc_tools.protoc", "--version")
    return python


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--output", required=True)
    args = parser.parse_args()

    output = Path(args.output).resolve()
    if output == ROOT or ROOT in output.parents:
        raise SystemExit("Output must be outside the repository")
    if output.exists() and any(output.iterdir()):
        raise SystemExit("Output directory must be empty")
    output.mkdir(parents=True, exist_ok=True)

    expected = []
    with tempfile.TemporaryDirectory(prefix="avos-protobuf-tools-") as work:
        tools = Path(work)
        bin_dir = tools / "bin"
        bin_dir.mkdir()

        environment = os.environ.copy()
        environment["GOBIN"] = str(bin_dir)
        environment["PATH"] = str(bin_dir) + os.pathsep + environment["PATH"]

        run(
            "go", "install",
            "google.golang.org/protobuf/cmd/protoc-gen-go@v1.34.2",
            env=environment,
        )
        run(
            "go", "install",
            "google.golang.org/grpc/cmd/protoc-gen-go-grpc@v1.5.1",
            env=environment,
        )

        compilers = {
            "legacy": python_environment(
                tools / "legacy", "1.76.0", "6.33.2"
            ),
            "assistant": python_environment(
                tools / "assistant", "1.84.0", "7.36.2"
            ),
        }

        proto_dir = ROOT / "protos"

        for service, schemas in GO_SERVICES.items():
            relative = Path("src") / service / "genproto"
            destination = output / relative
            destination.mkdir(parents=True)

            run(
                compilers["legacy"], "-m", "grpc_tools.protoc",
                f"-I{proto_dir}",
                f"--go_out={destination}",
                "--go_opt=paths=source_relative",
                f"--go-grpc_out={destination}",
                "--go-grpc_opt=paths=source_relative",
                *[str(proto_dir / schema) for schema in schemas],
                env=environment,
            )
            for schema in schemas:
                stem = Path(schema).stem
                expected.extend([
                    relative / f"{stem}.pb.go",
                    relative / f"{stem}_grpc.pb.go",
                ])

        for service, (compiler, schema) in PYTHON_SERVICES.items():
            relative = Path("src") / service
            destination = output / relative
            destination.mkdir(parents=True)

            run(
                compilers[compiler], "-m", "grpc_tools.protoc",
                f"-I{proto_dir}",
                f"--python_out={destination}",
                f"--grpc_python_out={destination}",
                str(proto_dir / schema),
            )
            stem = Path(schema).stem
            expected.extend([
                relative / f"{stem}_pb2.py",
                relative / f"{stem}_pb2_grpc.py",
            ])

    tracked = subprocess.check_output(
        ["git", "ls-files", "-z"], cwd=ROOT
    ).decode().split("\0")

    generated_pattern = re.compile(
        r"src/[^/]+/(?:genproto/[^/]+\.pb\.go|[^/]+_pb2(?:_grpc)?\.py)"
    )
    tracked_generated = {
        name for name in tracked if generated_pattern.fullmatch(name)
    }
    expected_names = {path.as_posix() for path in expected}

    if tracked_generated != expected_names:
        raise RuntimeError(
            "Generated-file inventory differs from the configured outputs.\n"
            f"Unconfigured: {sorted(tracked_generated - expected_names)}\n"
            f"Missing tracked files: {sorted(expected_names - tracked_generated)}"
        )

    differences = []
    changed = []

    for relative in sorted(expected):
        committed = ROOT / relative
        regenerated = output / relative
        original = committed.read_text(encoding="utf-8")
        fresh = regenerated.read_text(encoding="utf-8")

        # Preserve existing license notices before the generated-code header.
        prefix = original[:generated_start(original, relative.suffix)]
        body = fresh[generated_start(fresh, relative.suffix):]
        normalized = prefix + body
        regenerated.write_text(normalized, encoding="utf-8", newline="\n")

        if original != normalized:
            changed.append(relative.as_posix())
            differences.extend(difflib.unified_diff(
                original.splitlines(keepends=True),
                normalized.splitlines(keepends=True),
                fromfile=f"a/{relative.as_posix()}",
                tofile=f"b/{relative.as_posix()}",
            ))

    (output / "generated-files.txt").write_text(
        "\n".join(sorted(expected_names)) + "\n", encoding="utf-8"
    )
    (output / "drift.diff").write_text(
        "".join(differences), encoding="utf-8"
    )

    if changed:
        print("Generated protobuf files differ:", flush=True)
        for name in changed:
            print(f"  {name}", flush=True)
        print("Review drift.diff and regenerated files in the artifact.")
        return 1

    print(f"PASS: all {len(expected)} generated files match.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
